<template>
  <div
    class="h-full w-full bg-no-repeat bg-center bg-cover border shadow-md rounded-lg flex items-center justify-center relative"
    :class="{ 'opacity-50': isLoading, 'aspect-square max-w-60 max-h-60 sm:max-h-none sm:max-w-none': isSquare }"
    :style="{ backgroundImage: `url(${url})` }"
  >
    <!-- TODO: make isSquare more reusable or use new component for canvasser profile image on form -->
    <!-- TODO: add class for AppLoader to add opacity, not for div element -->
    <AppLoader v-if="isLoading" variant="inline" class="!min-h-0" title="" />
    <template v-else>
      <template v-if="isPreloader">
        <div
          class="absolute inset-0 flex items-center justify-center w-full h-full bg-black opacity-45 rounded-lg aspect-square"
        />
        <Spinner class="fill-card text-card stroke-card" />
      </template>
      <button
        v-if="!isPreloader"
        class="absolute top-2 right-2 md:top-2.5 md:right-2.5 bg-slate-500/70 duration-300 rounded-md"
        @click.prevent.stop="onDeleteClick"
      >
        <XIcon class="w-5 h-5 stroke-slate-100 hover:stroke-slate-800" />
      </button>
    </template>
  </div>
</template>

<script setup lang="ts">
import { XIcon } from 'lucide-vue-next';
import { Spinner } from '~/assets/icons';

interface Props {
  url: string;
  isLoading: boolean;
  isSquare?: boolean;
  isPreloader?: boolean;
  delete?: () => Promise<void>;
}

interface Emits {
  (e: 'delete'): void;
}

const props = defineProps<Props>();
const emit = defineEmits<Emits>();

async function onDeleteClick() {
  if (props.delete) {
    await props.delete();
  } else {
    emit('delete');
  }
}
</script>

<style scoped lang="scss"></style>
